INSERT OR REPLACE INTO events (event_id, status, featured, title, event_type, image_url, image_credit, cover_memory_id, organizer_reflection, facebook_album_url, custom_event_type, start_date, start_time, end_date, end_time, location_name, address, description, what_to_expect, what_to_bring, provided, special_notes, custom_acknowledgements, allow_flexible_attendance_dates, allow_organizer_provided_accommodation, allow_bring_own_accommodation, allow_participant_reserved_accommodation, allow_day_visitors, children_allowed, registration_required, free_event, paid_event, variable_cost, cost_details, adult_cost, child_cost, payment_due, venmo_enabled, venmo_handle, cash_app_enabled, cash_app_handle, cash_enabled, pay_at_event_enabled, buy_own_tickets_enabled, ticket_purchase_link, max_participants, waitlist_enabled, organizer_name, organizer_email, organizer_phone, organizer_photo_url, show_attendee_names, registration_link, drive_folder_id, created_by, created_at, updated_at) VALUES ('event_1cdfcee6eeab', 'Published', 1, 'Heroes Of The Sea', 'Travel & Vacations', 'https://drive.google.com/thumbnail?id=15Avaz5V8uDN-j12ziS_tXH--DSxDvBEp&sz=w1600', '', '', '', '', '', '2027-04-09', '4:00 PM', '2027-04-16', '7:00 AM', 'Caribbean', 'Orlando (Port Canaveral), Florida', 'What if you could leave behind the stress, alarms, radios, long shifts, appointments, and everyday chaos for an entire week?

Cruise For Heroes is a member-organized Community Connections adventure bringing together Veterans, Active Military, First Responders, Front-Line Workers, and their immediate family members for an unforgettable seven-night Caribbean vacation aboard the Norwegian Escape.

Whether you''ve cruised dozens of times or have never stepped on a cruise ship, this trip is about far more than the destinations. It''s about slowing down, laughing with people who understand your journey, building new friendships, and making memories that last long after everyone returns home.

Hosted by fellow IWP Member and cruiser Pete Davis, this adventure offers the perfect balance of relaxation and excitement. Spend your days lounging poolside, enjoying incredible dining, catching Broadway-style shows, exploring beautiful Caribbean islands, trying something adventurous, or simply sitting on deck with a drink while watching the ocean roll by.

The Norwegian Escape was selected because it truly has something for everyone. Families can enjoy the water park, ropes course, arcade, bowling alley, restaurants, and entertainment, while adults looking for peace and quiet can relax in adult-only areas, enjoy live music, unwind at the spa, or simply find a quiet place to enjoy the sunshine.

Even though the ship carries thousands of guests, it''s designed to spread everyone out remarkably well, making it easy to find both excitement and peaceful relaxation whenever you want.

🌴 Ports of Call

• 🇻🇮 St. Thomas, U.S. Virgin Islands
• 🇻🇬 Tortola, British Virgin Islands
• 🇩🇴 Puerto Plata, Dominican Republic
• 🇧🇸 Great Stirrup Cay, Bahamas

🛏 Cabin Options

Cabins are available in several categories, including:
• Solo Studio 1 Passenger Only 
• Interior for 2 
• Oceanview For 2 
• Balcony For 2 
• Club Balcony Suite For 2 
• Family Balcony For 4 

Cabins are expected to sell quickly, so booking early is strongly encouraged.

📞 Booking Information

This cruise is booked under a group reservation.
Travel Agent: Jo Anne Alexandra
Phone: 877-416-9722 ext. 36346
Group Booking Number: 3083606

Please reference the group booking number when reserving your cabin to receive the group pricing and included amenities.

Deposits remain fully refundable until the final payment deadline in December 2026.

Once your cabin is reserved, you''ll be able to choose your cabin location, reserve specialty dining, book shore excursions, and make payments toward your vacation whenever you''d like through Norwegian''s website or mobile app.

Whether you''re traveling solo, bringing your spouse, coming with friends, or meeting everyone for the first time, Cruise For Heroes is about stepping away from everyday life for a week and spending time with people who truly understand one another.

We can''t wait to see you onboard!', '• Seven unforgettable nights aboard the Norwegian Escape.

• Plenty of opportunities to relax, socialize, or enjoy time by yourself.

• Beautiful Caribbean destinations with optional shore excursions.

• Excellent restaurants, entertainment, shopping, casinos, live music, comedy, and activities throughout the ship.

• Time to build friendships with fellow Community Connections members.

• A casual, welcoming atmosphere with no pressure or scheduled group activities unless participants choose to organize them.

• Both experienced cruisers and first-time cruisers are encouraged to join.', '• Passport or any required travel documentation.

• Comfortable clothing for warm tropical weather.

• Swimsuits and beachwear.

• Casual clothes for evenings onboard.

• Any dressier clothing you''d like for specialty dining or formal nights.

• Walking shoes and sandals.

• Sunglasses, sunscreen, and a hat.

• Prescription medications.

• Spending money for souvenirs, casino play, premium activities, or optional purchases.

• Phone charger and charging cables.

• Excursion gear if participating in shore activities.

• A positive attitude and a willingness to meet some incredible people.', 'Every cabin booked within the group reservation includes:

• Unlimited beverage package (alcoholic and non-alcoholic beverages)

• Three specialty dining experiences (per two-person cabin)

• 150 minutes of Wi-Fi

• $100 onboard credit per cabin

• $50 discount on each shore excursion

• All meals throughout the cruise

• Broadway-style entertainment

• Access to pools, activities, entertainment, and ship amenities

Guests staying in Solo Studio cabins also receive exclusive access to the Studio Lounge with complimentary snacks, beverages, and social gatherings for solo travelers.', '• This is a member-organized Community Connections adventure and is not an official IWP event.

• Each participant is responsible for booking their own cruise reservation, airfare, transportation, lodging before or after the cruise if needed, travel documentation, and personal expenses.

• Travel insurance is highly recommended.

• Shore excursions are optional and may be reserved after your cruise deposit is made.

• Norwegian''s mobile app allows you to manage payments, reserve dining, and book excursions before departure.

• Cabins are limited and availability may change quickly.

• Everyone is welcome whether you''re traveling alone or with family members.

• Optional Pre-Cruise Stay: Several members are planning to fly into the Orlando area on April 8, the day before embarkation, and stay overnight at a nearby hotel. Arriving the night before helps make embarkation day much more relaxed by avoiding the stress of same-day travel delays. If you''d like to join us, you''re welcome to book a hotel for the night and start the adventure a little early!', '["I understand I am responsible for booking and paying for my own cruise reservation, transportation, lodging before or after the cruise if needed, and any other personal travel expenses.","I understand I am responsible for ensuring I have valid travel documents, including a passport if required, before traveling.","I understand I am responsible for arriving at the cruise terminal on time and that the ship cannot delay departure for late arrivals.","I understand I am responsible for complying with all Norwegian Cruise Line policies, ship rules, and applicable laws while traveling.","I understand I am responsible for my own medical needs, prescription medications, and notifying the cruise line of any accessibility or accommodation requirements.","I understand I am responsible for any optional purchases, shore excursions, gratuities, and personal expenses not included with my reservation."]', 0, 0, 0, 1, 0, 1, 1, 0, 1, 1, 'Pricing varies by cabin type and occupancy. All listed prices include applicable taxes, port fees, and the group amenities included with the reservation.

• Solo Studio 1 Passenger Only - $1748.50

• Interior for 2 (3rd & 4th passengers sail free in this same room. Those would only pay taxes, food & drink package, etc) Can split cost 4 ways but it will be tight fitting 😜) - $2479.10

• Oceanview For 2 - $2941.10

• Balcony For 2 - $3,085.20

• Club Balcony Suite For 2 - $3,175.20

• Family Balcony For 4 - $4,796.00', NULL, NULL, '', 0, '', 0, '', 0, 0, 1, '', NULL, 0, 'Pete Davis', '', '', 'https://drive.google.com/thumbnail?id=1-vobtivG6o2UdHq9EwpU3CZ7lQT6aB7T&sz=w1600', 1, 'https://script.google.com/macros/s/AKfycbxPNqswpRLvj0LZ0ZaVw6DTSpTcZIDt0S0zWFJgOES7g864n734dDF2UpGMwdpsEPGK4Q/exec?register=event_1cdfcee6eeab', '17yRpNoq_H-aUMqJylwsKDk42jm8mSVn0', '', '', '2026-07-25T21:17:10.464Z');
