INSERT OR REPLACE INTO registrations (registration_id, event_id, status, name, email, phone, adult_count, child_count, adult_guest_names, child_names, emergency_contact_name, emergency_contact_phone, payment_status, payment_method, payment_notes, show_name_on_attendee_list, acknowledgement_member_organized, acknowledgement_voluntary, acknowledgement_respect, acknowledgement_photos_videos, acknowledgement_payment, acknowledgement_refund, custom_acknowledgements_accepted, attendance_type, arrival_date, departure_date, day_visit_date, accommodation_type, accommodation_site_number, resource_reservations, notes, registered_at, updated_at) VALUES ('reg_fa9dd3022326', 'event_f460ed764cbb', 'Confirmed', 'Pete Davis', 'rcsort@icloud.com', '2182518614', 1, 0, '', '', 'Molly', '2182518780', 'Not Required', '', '', 1, 1, 1, 1, 1, 0, 0, '[{"text":"I voluntarily choose to participate in this tubing trip and understand that outdoor water activities involve inherent risks, including but not limited to: slipping, falling, drowning, collisions with people or objects, changing river conditions, weather, wildlife, equipment failure, transportation to and from the river, and other known or unknown hazards that may result in property damage, serious injury, illness, or death.","accepted":true},{"text":"I certify that I am physically able to participate and accept full responsibility for determining whether this activity is appropriate for me.","accepted":true},{"text":"By participating, I voluntarily assume all risks associated with this activity and release, waive, and hold harmless the event organizer(s), volunteer helpers, property owners, landowners, transportation providers, and Invisible Wounds Project from any claims, demands, causes of action, damages, losses, costs, or expenses arising from or related to my participation, except where prohibited by law or resulting from gross negligence or willful misconduct.","accepted":true},{"text":"I understand that tubing on a natural river involves inherent risks, including changing currents, submerged obstacles, uneven shorelines, and varying water conditions.","accepted":true},{"text":"I understand participation is entirely voluntary.","accepted":true},{"text":"I understand I am responsible for my own safety and personal belongings.","accepted":true},{"text":"I understand alcohol or drug impairment significantly increases the risks of river activities, and I am responsible for my own decisions.","accepted":true},{"text":"I understand I should wear a properly fitted U.S. Coast Guard-approved life jacket while on the water even though it is not required and doesn''t prevent me from going on this trip if I don''t.","accepted":true},{"text":"I understand river conditions can change rapidly, and no one can guarantee my safety.","accepted":true},{"text":"I understand in the event of an emergency, organizers may attempt to obtain medical assistance, but they are under no obligation to do so and are not responsible for any resulting medical expenses.","accepted":true},{"text":"I understand that I am responsible for ensuring any child I bring is at least 5 years old and remains under my direct supervision throughout the event.","accepted":true},{"text":"I understand that if I use tubing equipment provided by an organizer or another participant, I understand that it is provided \"as is\" without any warranty or guarantee of safety or fitness for any particular purpose. I accept full responsibility for inspecting any equipment before use and assume all risks associated with its use.","accepted":true},{"text":"I agree to arrive at Rush City Ferry Landing by 9:00 AM and understand the group will depart promptly at 9:30 AM without waiting for late arrivals.","accepted":true},{"text":"I understand that if I reserve an organizer-provided tube, it is intended for my use only during this event.","accepted":true},{"text":"I am responsible for bringing any personal equipment I choose to use, including my own tube, life jacket, water shoes, or other gear.","accepted":true},{"text":"I understand that weather or river conditions may require the organizer to delay, modify, or cancel the event for safety reasons.","accepted":true},{"text":"I agree to help keep the St. Croix River clean by packing out everything I bring with me and respecting the natural environment.","accepted":true},{"text":"I understand that participants will work together to coordinate transportation between the launch and take-out locations, and I agree to cooperate with those arrangements before and after the float.","accepted":true}]', 'Bring My Own', '2026-08-05', '2026-08-05', '', '', '', '[]', '', '2026-08-01T14:25:07.386Z', '2026-08-01T14:25:07.386Z');
